    hdcScreen = CreateDC("DISPLAY", NULL, NULL, NULL);
    hdcMem = CreateCompatibleDC(hdcScreen);

    hBitmap = CreateCompatibleBitmap(hdcScreen, GetSystemMetrics(SM_CXSCREEN), GetSystemMetrics(SM_CYSCREEN));
    hOldBitmap = (HBITMAP)SelectObject(hdcMem, hBitmap);

    BitBlt(hdcMem, 0, 0, GetSystemMetrics(SM_CXSCREEN), GetSystemMetrics(SM_CYSCREEN), hdcScreen, 0, 0, SRCCOPY);

    GetObject(hBitmap, sizeof(bitmap), &bitmap);

    // Set image dimensions
    image = CloneImage(NULL, bitmap.bmWidth, bitmap.bmHeight, MagickFalse, exception);
    if (!image)
        throw (0, "Memory allocation error", NULL);

    // Process each pixel and set color values in the image
    pixels = QueueAuthenticPixels(image, 0, 0, image->columns, image->rows, exception);
    if (!pixels)
        throw (0, "QueueAuthenticPixels failed", NULL);

    for (y = 0; y < (int)image->rows; y++) {
        for (x = 0; x < (int)image->columns; x++) {
            COLORREF color;
            offset = y * image->columns + x;
            color = GetPixel(hdcMem, x, y);

            pixels[offset].red = (Quantum) (GetRValue(color) * (QuantumRange / 255.0));
            pixels[offset].green = (Quantum) (GetGValue(color) * (QuantumRange / 255.0));
            pixels[offset].blue = (Quantum) (GetBValue(color) * (QuantumRange / 255.0));
            pixels[offset].opacity = Transparent ? OpaqueOpacity : TransparentOpacity;
        }
    }

    status = SyncAuthenticPixels(image, exception);
    if (!status)
        throw (0, "SyncAuthenticPixels failed", NULL);

    // Clean up resources
    SelectObject(hdcMem, hOldBitmap);
    DeleteDC(hdcMem);
    DeleteDC(hdcScreen);
    DeleteObject(hBitmap);
}

