void captureScreenToImage() {
    // Initialize image and wand context
    MagickWand *image_wand = NewMagickWand();

    HDC hdcScreen = GetDC(NULL);
    if (!hdcScreen) {
        DestroyMagickWand(image_wand);
        return;
    }

    HGDIOBJ hBitmap = CreateDIBSection(hdcScreen, NULL, DIB_RGB_COLORS, NULL, NULL, 0);
    if (!hBitmap) {
        ReleaseDC(NULL, hdcScreen);
        DestroyMagickWand(image_wand);
        return;
    }

    BITMAP bitmap;
    GetObject(hBitmap, sizeof(BITMAP), &bitmap);

    MagickSetSize(image_wand, bitmap.bmWidth, bitmap.bmHeight);
    MagickPixelPacket *pixels = MagickGetAuthenticPixels(image_wand, 0, 0, bitmap.bmWidth, bitmap.bmHeight);

    HDC hdcMem = CreateCompatibleDC(hdcScreen);
    SelectObject(hdcMem, hBitmap);
    BitBlt(hdcMem, 0, 0, bitmap.bmWidth, bitmap.bmHeight, hdcScreen, 0, 0, SRCCOPY);

    BYTE *src = bitmap.bmBits;
    for (int y = 0; y < bitmap.bmHeight; y++) {
        for (int x = 0; x < bitmap.bmWidth; x++) {
            MagickPixelPacket *pixel = &pixels[y * bitmap.bmWidth + x];
            pixel->red = (MagickRealType) src[2] / 255.0;
            pixel->green = (MagickRealType) src[1] / 255.0;
            pixel->blue = (MagickRealType) src[0] / 255.0;
            pixel->alpha = 1.0;
            src += 3;
        }
    }

    MagickSyncAuthenticPixels(image_wand);

    DeleteDC(hdcMem);
    ReleaseDC(NULL, hdcScreen);
    DeleteObject(hBitmap);
}

